-- The real bottle catalogue replaces the sample bottles. One product per design and bottle style;
-- the colours a design comes in are its colour options, each with a cut-out and a photo.
-- Prices are the earlier per-style prices (Midnight Fury is a first guess); stock counts are first values.

begin;

update public.products set contains = array_replace(contains, 'wellspring-bottle', 'psalm-91-flowstate'), updated_at = now() where slug = 'joy-hamper';

delete from public.products where slug in ('mood-mug', 'thirst-crusher', 'flowstate-bottles', 'slim-sip', 'tiny-tank', 'wellspring-bottle');


























































commit;
